const input = $input.first().json;
const payload = input.body && typeof input.body === 'object' ? input.body : input;
const controlRepository = 'nario0715masa0619-create/luvira-ai-devflow';
const projectId = typeof payload.project_id === 'string' ? payload.project_id.trim() : '';
const repository = typeof payload.repository === 'string' ? payload.repository.trim() : '';
if (!/^project-[a-z][a-z0-9-]{2,62}$/.test(projectId)) throw new Error('ORCA_PRODUCT_PROJECT_ID_INVALID');
if (!/^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$/.test(repository) || repository === controlRepository || repository === 'nario0715masa0619-create/luvira-ai-devflow-staging') throw new Error('ORCA_PRODUCT_REPOSITORY_INVALID');
for (const key of ['request', 'task_type', 'requested_action', 'expiry']) { if (typeof payload[key] !== 'string' || !payload[key].trim()) throw new Error(`ORCA_PRODUCT_${key.toUpperCase()}_INVALID`); }
if (!Array.isArray(payload.allowed_paths) || !payload.allowed_paths.length || !Array.isArray(payload.source_paths) || !payload.source_paths.length || !Array.isArray(payload.acceptance_criteria) || !payload.acceptance_criteria.length || !Number.isFinite(payload.max_cost_usd) || payload.max_cost_usd <= 0) throw new Error('ORCA_PRODUCT_SCOPE_INVALID');
const pathInvalid = value => typeof value !== 'string' || !value || value.startsWith('/') || value.includes('\') || value.split('/').includes('..');
if ([...payload.allowed_paths, ...payload.source_paths].some(pathInvalid)) throw new Error('ORCA_PRODUCT_SCOPE_INVALID');
if (!['implementation', 'documentation', 'test', 'validation'].includes(payload.task_type) || !['read', 'plan', 'comment', 'implementation'].includes(payload.requested_action)) throw new Error('ORCA_PRODUCT_ACTION_INVALID');
const criteria = payload.acceptance_criteria.map(value => `- ${String(value).trim()}`).join('
');
const allowed = JSON.stringify([...new Set(payload.allowed_paths)].sort());
const source = JSON.stringify([...new Set(payload.source_paths)].sort());
const impact = `対象リポジトリ: ${repository}
変更許可: ${allowed}
参照許可: ${source}
最大コスト: $${payload.max_cost_usd}`;
const body = `### Project ID

${projectId}

### Repository

${repository}

### 承認すること

${payload.request.trim()}

### タスク種別

${payload.task_type}

### 受入条件

${criteria}

### 最大コスト（USD）

${payload.max_cost_usd}

### 影響

${impact}

### しないこと

許可パス外の変更、秘密情報・権限・本番環境の変更、承認前の実装実行

### 許可するリポジトリ内パス

${allowed}

### 参照を許可するリポジトリ内パス

${source}

### 許可を求める最初のアクション

${payload.requested_action}

### 有効期限（UTC）

${payload.expiry}`;
return [{ json: { control_repository: controlRepository, title: `[AI Approval]: ${payload.request.trim().slice(0, 70)}`, issue_body: body } }];

const issue = $input.first().json;
if (!Number.isInteger(issue.number) || typeof issue.html_url !== 'string') throw new Error('ORCA_PRODUCT_ISSUE_CREATE_INVALID');
return [{ json: { status: 'AWAITING_HUMAN_APPROVAL', issue_number: issue.number, issue_url: issue.html_url } }];
